struct Em<'a> {
    scope: &'a str,
    next: usize,
    ins: Vec<Instruction>,
}
impl<'a> Em<'a> {
    fn imm(v: u128) -> Operand {
        Operand::Immediate(Fr::from(v))
    }
    fn t(&mut self) -> Identifier {
        let id = Identifier(format!("%{}.local.temp.{}", self.scope, self.next));
        self.next += 1;
        id
    }
    fn cbool(&mut self, v: Operand) {
        self.ins.push(Instruction::ConstrainToBoolean { val: v });
    }
    fn cbits(&mut self, v: Operand) {
        self.ins.push(Instruction::ConstrainBits {
            val: v,
            bits: LANE_BITS,
        });
    }
    fn ceq(&mut self, a: Operand, b: Operand) {
        self.ins.push(Instruction::ConstrainEq { a, b });
    }
    fn teq(&mut self, a: Operand, b: Operand) -> Operand {
        let o = self.t();
        self.ins.push(Instruction::TestEq {
            a,
            b,
            output: o.clone(),
        });
        Operand::Variable(o)
    }
    fn lt128(&mut self, a: Operand, b: Operand) -> Operand {
        let o = self.t();
        self.ins.push(Instruction::LessThan {
            a,
            b,
            bits: LANE_BITS,
            output: o.clone(),
        });
        Operand::Variable(o)
    }
    fn add(&mut self, a: Operand, b: Operand) -> Operand {
        let o = self.t();
        self.ins.push(Instruction::Add {
            a,
            b,
            output: o.clone(),
        });
        Operand::Variable(o)
    }
    fn mul(&mut self, a: Operand, b: Operand) -> Operand {
        let o = self.t();
        self.ins.push(Instruction::Mul {
            a,
            b,
            output: o.clone(),
        });
        Operand::Variable(o)
    }
    fn not(&mut self, a: Operand) -> Operand {
        let o = self.t();
        self.ins.push(Instruction::Not {
            a,
            output: o.clone(),
        });
        Operand::Variable(o)
    }
    fn sel(&mut self, bit: Operand, a: Operand, b: Operand) -> Operand {
        let o = self.t();
        self.ins.push(Instruction::CondSelect {
            bit,
            a,
            b,
            output: o.clone(),
        });
        Operand::Variable(o)
    }
    fn assert_t(&mut self, c: Operand) {
        self.ins.push(Instruction::Assert { cond: c });
    }
    fn geq(&mut self, g: Operand, a: Operand, b: Operand) {
        let s = self.sel(g, a, b.clone());
        self.ceq(s, b);
    }
    fn gassert(&mut self, g: Operand, c: Operand) {
        let e = self.sel(g, c, Self::imm(1));
        self.assert_t(e);
    }
    fn gzero(&mut self, g: Operand, v: Operand) {
        self.geq(g, v, Self::imm(0));
    }
    fn and(&mut self, a: Operand, b: Operand) -> Operand {
        self.mul(a, b)

//! C6 legacy control step: the remaining legacy `k.machine.*` rows factorial
//! and fold fire, as one per-rule relation over the full C6 carriers:
//! `return.unary`, `return.if.true`, `return.if.false`, `return.match`,
//! `return.arguments.final` (frame pops), `primitive.value`, `cases.try`,
//! `cases.miss` and `cases.hit` (control rewrites).
//!
//! Each circuit fixes its rule at build time, selects it with the composed
//! dispatch owner and writes the post control, control origin, env root,
//! frame stack and helper result exactly as `fragments/legacy.proposed.rs`
//! plans them. A pop decrements the depth and zeroes the popped slot.
//! `cases.try` reads the first arm's body from canonical PROG. Charge is
//! LegacyComplete (work 1, reference cursor 1). Every unnamed lane is
//! preserved; canonicality is composed; enable = 0 is identity.
