            running,
            no_helper,
            no_result,
            ct,
            k,
            depth,
            depth_zero,
            stack_limit,
            fuel_zero,
            top,
            eval_row,
            origin_row,
            functions_count: cap.functions_count,
            site,
            site_defined,
            htag,
            h,
            rt,
            r1,
            live_pos,
            task,
            validate_marker,
            equal_differ,
