pub struct C6Root {
    pub control: ControlC,
    pub control_origin: usize,
    pub env_root: EnvRootC,
    pub stack_limit: usize,
    pub outcome: OutcomeC,
    pub initial_fuel: u128,
    pub remaining_work: u128,
    pub consumed_work: u128,
    pub helper_work: u128,
    pub helper_visits: u128,
    pub reference_cursor: u128,
    pub alloc: AllocCounters,
    pub active: ActiveLengths,
    pub seg_active: ActiveLengths,
    pub seg_alloc: AllocCounters,
    pub seg_consumed_work: u128,
}

impl C6Root {
    /// Projection of the owned image registers; no field is invented.
    pub fn from_image(image: &ImageSnapshot) -> Self {
        Self {
            control: image.control,
            control_origin: image.control_origin,
            env_root: image.env_root,
            stack_limit: image.stack_limit,
            outcome: image.outcome,
            initial_fuel: image.initial_fuel,
            remaining_work: image.remaining_work,
            consumed_work: image.consumed_work,
            helper_work: image.helper_work,
            helper_visits: image.helper_visits,
            reference_cursor: image.reference_cursor,
            alloc: image.alloc,
            active: image.active,
            seg_active: image.seg_base.active(),
            seg_alloc: image.seg_base.alloc(),
            seg_consumed_work: image.seg_base.consumed_work(),
        }
    }
}

fn root_caps(root: &C6Root, c: &C6PhysCaps) -> C6Result<()> {
    control_caps(&root.control, c)?;
    cap_index(
        "root.control_origin",
        root.control_origin,
        c.max_expressions,
    )?;
    cap_env("root.env_root", root.env_root, c)?;
    cap_count("root.stack_limit", root.stack_limit, c.max_frames)?;
    if let OutcomeC::Halted { value } = root.outcome {
        cap_ref("root.outcome", value, c)?;
    }
    for (section, needed, limit) in [
        (
            "root.alloc.data_nodes",
            root.alloc.data_nodes,
            c.max_data_nodes,
        ),
        (
            "root.alloc.environment_cells",
            root.alloc.environment_cells,
            c.max_env_cells,
        ),
        ("root.active.data", root.active.data, c.max_data_nodes),
        ("root.active.env", root.active.env, c.max_env_cells),
        (
            "root.active.value_slots",
            root.active.value_slots,
            c.max_value_slots,
        ),
        (
            "root.seg_active.data",
            root.seg_active.data,
            c.max_data_nodes,
        ),
        ("root.seg_active.env", root.seg_active.env, c.max_env_cells),
        (
            "root.seg_active.value_slots",
            root.seg_active.value_slots,
            c.max_value_slots,
        ),
        (
            "root.seg_alloc.data_nodes",
            root.seg_alloc.data_nodes,
            c.max_data_nodes,
        ),
        (
            "root.seg_alloc.environment_cells",
            root.seg_alloc.environment_cells,
            c.max_env_cells,
        ),
    ] {
        cap_count(section, needed, limit)?;
    }
    Ok(())
}

