    // register, or program read precedes the binding check.
    pub fn bind(admitted: &'a Admitted, img: &'a MachineImage) -> Result<Self, HostViolation> {
        if Arc::ptr_eq(&admitted.body, &img.admission.body) {
            Ok(Self { admitted, img })
        } else {
            Err(HostViolation {
                kind: HostViolationKind::StepInvViolated,
                clause: Some(StepInvClauseId::SI01),
                rule: None,
                locator: Some("admission binding".to_string()),
            })
        }
    }
