fn check_copied_envs(
    pre: &PreImage,
    w: &PlannedWrites,
    envs: &[usize],
) -> Result<(), HostViolation> {
    let fresh = if w.alloc_env.is_some() {
        Some(pre.img.active.env)
    } else {
        None
    };
    let mut written: Vec<EnvRootC> = Vec::new();
    if let Write::Set(c) = &w.control {
        match c {
            ControlC::ScheduleNext { frame, env, .. } => {
                written.push(frame_env(frame));
                written.push(*env);
            }
            ControlC::Bound {
                binding: BoundBinding::Ok { env },
                ..
            } => written.push(*env),
            ControlC::Cases { saved_env, .. } => written.push(*saved_env),
            ControlC::CaseResult {
                matching,
                saved_env,
                ..
            } => {
                written.push(*saved_env);
                if let CaseMatching::Matched { env } = matching {
                    written.push(*env);
