    if let Write::Set(Some(h)) = &w.helper {
        match h {
            HelperControlC::EnvGet { cursor, .. } => written.push(*cursor),
            HelperControlC::EnvPut { base, new_root, .. } => {
                written.push(*base);
                written.push(*new_root);
            }
            HelperControlC::Bind {
                partial,
                dup_cursor,
                ..
            } => {
                written.push(*partial);
                written.push(*dup_cursor);
            }
            HelperControlC::Match {
                saved_env, partial, ..
            }
            | HelperControlC::Plan {
                saved_env, partial, ..
            } => {
                written.push(*saved_env);
                written.push(*partial);
            }
            _ => {}
        }
    }
    if let Write::Set(Some(r)) = &w.result {
        match r {
            HelperResultC::EnvUpdated { cell } => written.push(Some(*cell)),
            HelperResultC::BindOk { env }
            | HelperResultC::MatchMatched { env }
            | HelperResultC::PlanMatched { env, .. } => written.push(*env),
            _ => {}
        }
    }
    let copied = |id: usize| id < pre.img.active.env && envs.contains(&id);
    for id in written.into_iter().flatten() {
        if Some(id) != fresh && !copied(id) {
            return Err(invalid_plan("SC-07 copied environment provenance"));
        }
    }
    if let Some(p) = w.alloc_env.and_then(|cell| cell.previous) {
        if !copied(p) {
            return Err(invalid_plan("SC-07 alloc_env.previous provenance"));
        }
    }
    Ok(())
}
