        owner_is_function: occurrence.owner_is_function,
        function: occurrence.function,
        ast_path: pre.occurrence_path(&occurrence.path)?.to_vec(),
    };
    Ok(Snap {
        consumed: img.consumed_work,
        cursor: img.reference_cursor,
        origin: img.control_origin,
        helper: img.helper,
        result: img.result,
        result_plan,
        depth: img.frames.len(),
        tasks: img.tasks.len(),
        source_occurrence,
    })
}
